import eventStream from "./EventStream.js";
export function healthCheck(_req, res) {
    return res.status(200).json({
        status: "success",
        message: "Server is healthy"
    });
}
export async function fallbackRoute(req, res) {
    eventStream.emitEvent("fallback", {
        headers: req.headers,
        data: req.body
    });
    return res.status(404).json({
        success: false,
        message: `Route ${req.method} ${req.originalUrl} not found`
    });
}
export function errorRoute(error, req, res, next) {
    const { status: statusCode, message } = error;
    eventStream.emitEvent("error", error);
    return res
        .status(statusCode ?? 404)
        .json({
        status: "error",
        message
    });
}
export function setOrigin(origin = null) {
    return function (req, res, next) {
        req.origin = (!origin) ? req.host : origin;
        next();
    };
}
